package org.thymeleaf.spring5.view.reactive;

import static org.mockito.Mockito.mock;

import java.util.Locale;

import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.web.server.ServerWebExchange;

import reactor.core.publisher.Mono;
import static org.junit.jupiter.api.Assertions.*;

import org.thymeleaf.spring5.ISpringWebFluxTemplateEngine;

public class ThymeleafReactiveViewRenderFragmentInternalTests {

    // A minimal concrete subject to control the values returned by protected accessors.
    private static class TestSubject extends ThymeleafReactiveView {
        private final String templateName;
        private final Locale locale;
        private final ISpringWebFluxTemplateEngine templateEngine;

        TestSubject(String templateName, Locale locale, ISpringWebFluxTemplateEngine templateEngine) {
            this.templateName = templateName;
            this.locale = locale;
            this.templateEngine = templateEngine;
        }

        @Override
        public String getTemplateName() {
            return templateName;
        }

        @Override
        public Locale getLocale() {
            return locale;
        }

        @Override
        public ISpringWebFluxTemplateEngine getTemplateEngine() {
            return templateEngine;
        }
    }

    @Test
    void whenTemplateNameIsNull_renderFragmentInternal_shouldReturnIllegalArgumentException() {
        ISpringWebFluxTemplateEngine engine = mock(ISpringWebFluxTemplateEngine.class);
        TestSubject subject = new TestSubject(null, Locale.US, engine);

        ServerWebExchange exchange = mock(ServerWebExchange.class);
        Mono<Void> result = subject.renderFragmentInternal(null, null, MediaType.TEXT_HTML, exchange);

        try {
            result.block();
            fail("Expected IllegalArgumentException");
        } catch (Throwable t) {
            Throwable e = (t.getCause() != null) ? t.getCause() : t;
            assertTrue(e instanceof IllegalArgumentException);
            assertEquals("Property 'templateName' is required", e.getMessage());
        }
    }

    @Test
    void whenLocaleIsNull_renderFragmentInternal_shouldReturnIllegalArgumentException() {
        ISpringWebFluxTemplateEngine engine = mock(ISpringWebFluxTemplateEngine.class);
        TestSubject subject = new TestSubject("sampleTemplate", null, engine);

        ServerWebExchange exchange = mock(ServerWebExchange.class);
        Mono<Void> result = subject.renderFragmentInternal(null, null, MediaType.TEXT_HTML, exchange);

        try {
            result.block();
            fail("Expected IllegalArgumentException");
        } catch (Throwable t) {
            Throwable e = (t.getCause() != null) ? t.getCause() : t;
            assertTrue(e instanceof IllegalArgumentException);
            assertEquals("Property 'locale' is required", e.getMessage());
        }
    }

    @Test
    void whenTemplateEngineIsNull_renderFragmentInternal_shouldReturnIllegalArgumentException() {
        // Do not provide a template engine; ensure the error is raised for missing engine.
        TestSubject subject = new TestSubject("sampleTemplate", Locale.US, null);

        ServerWebExchange exchange = mock(ServerWebExchange.class);
        Mono<Void> result = subject.renderFragmentInternal(null, null, MediaType.TEXT_HTML, exchange);

        try {
            result.block();
            fail("Expected IllegalArgumentException");
        } catch (Throwable t) {
            Throwable e = (t.getCause() != null) ? t.getCause() : t;
            assertTrue(e instanceof IllegalArgumentException);
            assertEquals("Property 'thymeleafTemplateEngine' is required", e.getMessage());
        }
    }

    // Keeps the tests focused on precondition validation as described in the specification.
}

package org.thymeleaf.spring5.view.reactive;

import java.util.Locale;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ThymeleafReactiveViewRenderFragmentInternalTests {

    @Test
    void rejectsRenderingWhenTemplateNameIsMissing() {
        TestView view = new TestView();

        Mono<Void> result = view.invoke(null, null, MediaType.TEXT_HTML, null);

        IllegalArgumentException error =
                assertThrows(IllegalArgumentException.class, result::block);

        assertEquals("Property 'templateName' is required", error.getMessage());
    }

    @Test
    void rejectsRenderingWhenLocaleIsMissing() {
        TestView view = new TestView();
        view.setTemplateName("home");

        Mono<Void> result = view.invoke(null, null, MediaType.TEXT_HTML, null);

        IllegalArgumentException error =
                assertThrows(IllegalArgumentException.class, result::block);

        assertEquals("Property 'locale' is required", error.getMessage());
    }

    @Test
    void rejectsRenderingWhenTemplateEngineIsMissing() {
        TestView view = new TestView();
        view.setTemplateName("home");
        view.locale = Locale.US;

        Mono<Void> result = view.invoke(null, null, MediaType.TEXT_HTML, null);

        IllegalArgumentException error =
                assertThrows(IllegalArgumentException.class, result::block);

        assertEquals(
                "Property 'thymeleafTemplateEngine' is required",
                error.getMessage());
    }

    private static final class TestView extends ThymeleafReactiveView {

        private Locale locale;

        @Override
        protected Locale getLocale() {
            return locale;
        }

        Mono<Void> invoke(
                Set<String> markupSelectorsToRender,
                Map<String, Object> renderAttributes,
                MediaType contentType,
                ServerWebExchange exchange) {

            return renderFragmentInternal(
                    markupSelectorsToRender,
                    renderAttributes,
                    contentType,
                    exchange);
        }
    }
}

