/**
 * Tests for ThymeleafReactiveView.renderFragmentInternal preconditions and basic behavior.
 * Focuses on observable behavior that distinguishes a correct implementation from potential defects
 * in the provided implementation, by validating argument preconditions.
 */
public class ThymeleafReactiveViewRenderFragmentInternalTests {

    /**
     * Simple Test subclass to expose the protected renderFragmentInternal method for testing.
     * This keeps the production behavior intact while allowing tests to trigger the
     * protected path with controlled inputs.
     */
    static class TestThymeleafReactiveView extends ThymeleafReactiveView {
        public Mono<Void> callRenderFragmentInternal(
                final Set<String> markupSelectorsToRender,
                final Map<String, Object> renderAttributes,
                final MediaType contentType,
                final ServerWebExchange exchange) {
            return super.renderFragmentInternal(markupSelectorsToRender, renderAttributes, contentType, exchange);
        }
    }

    @Test
    void testMissingTemplateNameThrowsIllegalArgumentException() {
        final TestThymeleafReactiveView view = new TestThymeleafReactiveView();
        // Do not set templateName to trigger precondition
        view.setLocale(Locale.ENGLISH);

        final ServerWebExchange exchange = mock(ServerWebExchange.class);

        final Mono<Void> result = view.callRenderFragmentInternal(null, null, MediaType.APPLICATION_JSON, exchange);

        Throwable thrown = null;
        try {
            result.block();
            fail("Expected IllegalArgumentException due to missing templateName");
        } catch (Throwable ex) {
            thrown = ex.getCause() != null ? ex.getCause() : ex;
        }

        assertNotNull(thrown, "An exception should have been thrown");
        assertTrue(thrown instanceof IllegalArgumentException);
        assertTrue(thrown.getMessage().contains("templateName"));
    }

    @Test
    void testMissingLocaleThrowsIllegalArgumentException() {
        final TestThymeleafReactiveView view = new TestThymeleafReactiveView();
        // Provide a non-null templateName to reach the locale check
        view.setTemplateName("templateName");
        // Do not set locale to trigger precondition
        final ServerWebExchange exchange = mock(ServerWebExchange.class);

        final Mono<Void> result = view.callRenderFragmentInternal(null, null, MediaType.APPLICATION_JSON, exchange);

        Throwable thrown = null;
        try {
            result.block();
            fail("Expected IllegalArgumentException due to missing locale");
        } catch (Throwable ex) {
            thrown = ex.getCause() != null ? ex.getCause() : ex;
        }

        assertNotNull(thrown, "An exception should have been thrown");
        assertTrue(thrown instanceof IllegalArgumentException);
        assertTrue(thrown.getMessage().contains("locale"));
    }

    @Test
    void testMissingTemplateEngineThrowsIllegalArgumentException() {
        final TestThymeleafReactiveView view = new TestThymeleafReactiveView();
        // Provide required values except the engine
        view.setTemplateName("templateName");
        view.setLocale(Locale.ENGLISH);
        // Do not set a template engine to trigger precondition
        final ServerWebExchange exchange = mock(ServerWebExchange.class);

        final Mono<Void> result = view.callRenderFragmentInternal(null, null, MediaType.APPLICATION_JSON, exchange);

        Throwable thrown = null;
        try {
            result.block();
            fail("Expected IllegalArgumentException due to missing thymeleafTemplateEngine");
        } catch (Throwable ex) {
            thrown = ex.getCause() != null ? ex.getCause() : ex;
        }

        assertNotNull(thrown, "An exception should have been thrown");
        assertTrue(thrown instanceof IllegalArgumentException);
        assertTrue(thrown.getMessage().contains("thymeleafTemplateEngine"));
    }
