package org.thymeleaf.spring6.view.reactive;

import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Locale;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import org.springframework.web.server.ServerWebExchange;
import org.thymeleaf.spring6.ISpringWebFluxTemplateEngine;
import reactor.core.publisher.Mono;

class ThymeleafReactiveViewRenderFragmentInternalTests {

    @Test
    void returnsAnErrorWhenTemplateNameIsNotConfigured() {
        TestView view = new TestView();

        assertThrows(
                IllegalArgumentException.class,
                () -> view.invoke(null, null, MediaType.TEXT_HTML, null).block());
    }

    @Test
    void returnsAnErrorWhenLocaleIsNotConfigured() {
        TestView view = new TestView();
        view.setTemplateName("home");

        assertThrows(
                IllegalArgumentException.class,
                () -> view.invoke(null, null, MediaType.TEXT_HTML, null).block());
    }

    @Test
    void returnsAnErrorWhenTemplateEngineIsNotConfigured() {
        TestView view = new TestView();
        view.setTemplateName("home");
        view.setViewLocale(Locale.US);

        assertThrows(
                IllegalArgumentException.class,
                () -> view.invoke(null, null, MediaType.TEXT_HTML, null).block());
    }

    private static final class TestView extends ThymeleafReactiveView {

        void setViewLocale(Locale locale) {
            setLocale(locale);
        }

        Mono<Void> invoke(
                Set<String> markupSelectorsToRender,
                Map<String, Object> renderAttributes,
                MediaType contentType,
                ServerWebExchange exchange) {
            return renderFragmentInternal(
                    markupSelectorsToRender,
                    renderAttributes,
                    contentType,
                    exchange);
        }

        @SuppressWarnings("unused")
        void setViewTemplateEngine(ISpringWebFluxTemplateEngine templateEngine) {
            setTemplateEngine(templateEngine);
        }
    }
}

