package org.thymeleaf;

import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.Test;

public class DialectSetConfigurationBuildTests {

    @Test
    void buildNullInputThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, () -> DialectSetConfiguration.build(null));
    }

    @Test
    void buildEmptyInputReturnsNonNullConfiguration() {
        final Set<DialectConfiguration> emptyConfigs = Collections.emptySet();
        final DialectSetConfiguration config = DialectSetConfiguration.build(emptyConfigs);
        assertNotNull(config);
    }
}

package org.thymeleaf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.thymeleaf.dialect.IDialect;
import org.thymeleaf.standard.StandardDialect;
import org.thymeleaf.templatemode.TemplateMode;

class DialectSetConfigurationBuildTests {

    @Test
    void buildAggregatesConfiguredStandardDialectAndItsProcessors() {
        final StandardDialect dialect = new StandardDialect();
        final String prefix = "app";
        final DialectConfiguration dialectConfiguration =
                new DialectConfiguration(prefix, dialect);

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(Collections.singleton(dialectConfiguration));

        assertNotNull(configuration);
        assertEquals(Collections.singleton(dialectConfiguration),
                configuration.getDialectConfigurations());

        final Set<IDialect> dialects = configuration.getDialects();
        assertEquals(1, dialects.size());
        assertTrue(dialects.contains(dialect));

        assertTrue(configuration.isStandardDialectPresent());
        assertEquals(prefix, configuration.getStandardDialectPrefix());

        assertFalse(configuration.getElementProcessors(TemplateMode.HTML).isEmpty());
        assertNotNull(configuration.getElementDefinitions());
        assertNotNull(configuration.getAttributeDefinitions());
        assertNotNull(configuration.getExpressionObjectFactory());
    }

    @Test
    void buildRejectsNullDialectConfigurationSet() {
        assertThrows(IllegalArgumentException.class,
                () -> DialectSetConfiguration.build(null));
    }

    @Test
    void buildAcceptsAnEmptyDialectConfigurationSet() {
        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(Collections.emptySet());

        assertNotNull(configuration);
        assertTrue(configuration.getDialectConfigurations().isEmpty());
        assertTrue(configuration.getDialects().isEmpty());
        assertFalse(configuration.isStandardDialectPresent());
        assertTrue(configuration.getExecutionAttributes().isEmpty());
        assertTrue(configuration.getElementProcessors(TemplateMode.HTML).isEmpty());
    }
}

