public boolean process() {


        /*
         * First, check the stopProcess flag
         */
        final TemplateFlowController flowController = getFlowController();
        if (flowController != null && flowController.stopProcessing) {
            return false;
        }

        if (this.offset == 0) {
            /*
             * Reset the "skipBody" and "skipCloseTag" values at the event model controller, and also set this
             * synthetic model into the processor handler so that it can be used by the executed events
             */
            prepareProcessing();
        }

        /*
         * PROCESS THE MODEL
         */
        final Model model = getInnerModel();
        this.offset += model.process(getProcessorTemplateHandler(), this.offset, flowController);

        /*
         * Compute whether the whole model has been processed or not
         */
        final boolean processed =
                (flowController == null || (this.offset == model.queueSize && !flowController.stopProcessing));

        if (processed) {
            /*
             * DECREASE THE CONTEXT LEVEL
             * This was increased before starting gathering, when the handling of the first gathered event started.
             */
            this.context.decreaseLevel();
        }

        return processed;

    }

Model(final IModel model) {

        super();

        Validate.notNull(model, "Model cannot be null");

        this.configuration = model.getConfiguration();
        this.templateMode = model.getTemplateMode();

        if (model instanceof Model) {

            final Model mmodel = (Model) model;
            this.queue = mmodel.queue.clone();
            this.queueSize = mmodel.queueSize;

        } else if (model instanceof TemplateModel) {

            final TemplateModel templateModel = (TemplateModel) model;
            this.queue = new IEngineTemplateEvent[templateModel.queue.length + INITIAL_EVENT_QUEUE_SIZE/2];
            System.arraycopy(templateModel.queue, 1, this.queue, 0, templateModel.queue.length - 2);
            this.queueSize = templateModel.queue.length - 2;

        } else {

            this.queue = new IEngineTemplateEvent[INITIAL_EVENT_QUEUE_SIZE];
            Arrays.fill(this.queue, null);
            this.queueSize = 0;
            insertModel(0, model);

        }

    }

ProcessorExecutionVars() {
        super();
        this.processorIterator = new ElementProcessorIterator();
