package org.thymeleaf.engine;

import static org.mockito.Mockito.*;

import java.lang.reflect.Field;

import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.thymeleaf.engine.ITemplateHandler;
import org.thymeleaf.model.IStandaloneElementTag;
import org.thymeleaf.engine.ProcessorTemplateHandler;
import org.thymeleaf.engine.TemplateModelController;

public class ProcessorTemplateHandlerHandleStandaloneElementTests {

    @Test
    public void testHandleStandaloneElement_shouldNotProcessWhenModelControllerSaysFalse() throws Exception {
        // Arrange
        final ProcessorTemplateHandler handler = new ProcessorTemplateHandler();

        // Create a mock ModelController to control processing decision
        final TemplateModelController mockModelController = mock(TemplateModelController.class, Mockito.RETURNS_DEFAULTS);
        when(mockModelController.shouldProcessStandaloneElement(any(IStandaloneElementTag.class))).thenReturn(false);

        // Inject the mocked controller into the handler via reflection
        final Field modelControllerField = ProcessorTemplateHandler.class.getDeclaredField("modelController");
        modelControllerField.setAccessible(true);
        modelControllerField.set(handler, mockModelController);

        // Create a mock next handler to verify that processing does not advance
        final ITemplateHandler mockNext = mock(ITemplateHandler.class);
        handler.setNext(mockNext);

        // Mock input tag
        final IStandaloneElementTag istandaloneElementTag = mock(IStandaloneElementTag.class);

        // Act
        handler.handleStandaloneElement(istandaloneElementTag);

        // Assert
        // When the modelController says we should not process this standalone element, the next handler should not be invoked
        verify(mockNext, never()).handleStandaloneElement(any(IStandaloneElementTag.class));
    }
}

package org.thymeleaf.engine;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.dialect.AbstractProcessorDialect;
import org.thymeleaf.model.IProcessableElementTag;
import org.thymeleaf.processor.IProcessor;
import org.thymeleaf.processor.element.AbstractElementTagProcessor;
import org.thymeleaf.processor.element.IElementTagStructureHandler;
import org.thymeleaf.templatemode.TemplateMode;
import org.thymeleaf.templateresolver.StringTemplateResolver;

class ProcessorTemplateHandlerHandleStandaloneElementTests {

    @Test
    void standaloneElementProcessorCanRemoveTheElementFromTheOutput() {
        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(TemplateMode.HTML);
        resolver.setCacheable(false);

        final TemplateEngine templateEngine = new TemplateEngine();
        templateEngine.setTemplateResolver(resolver);
        templateEngine.addDialect(new RemovingDialect());

        final String result = templateEngine.process(
                "<p:remove xmlns:p=\"urn:test\"/>",
                new Context());

        assertEquals("", result);
    }

    private static final class RemovingDialect extends AbstractProcessorDialect {

        private RemovingDialect() {
            super("Removing dialect", "p", 1000);
        }

        @Override
        public Set<IProcessor> getProcessors(final String dialectPrefix) {
            return Collections.singleton(new RemoveElementProcessor(dialectPrefix));
        }
    }

    private static final class RemoveElementProcessor extends AbstractElementTagProcessor {

        private RemoveElementProcessor(final String dialectPrefix) {
            super(
                    TemplateMode.HTML,
                    dialectPrefix,
                    "remove",
                    true,
                    null,
                    false,
                    1000);
        }

        @Override
        protected void doProcess(
                final org.thymeleaf.context.ITemplateContext context,
                final IProcessableElementTag tag,
                final IElementTagStructureHandler structureHandler) {
            structureHandler.removeElement();
        }
    }
}

