import org.thymeleaf.processor.element.IElementProcessor;
import org.thymeleaf.processor.element.IElementTagProcessor;
import org.thymeleaf.engine.ITemplateHandler;

/**
 * Test for ProcessorTemplateHandler.handleOpenElement with focus on observable public behavior
 * under controlled circumstances using Mockito.
 * The production classes used are mocked/stubbed where necessary to surface behavior differences.
 */
public class ProcessorTemplateHandlerHandleOpenElementTests {

    private ProcessorTemplateHandler handler;
    private ITemplateContext context;
    private ITemplateHandler nextHandler;

    @BeforeEach
    public void setUp() {
        // Create a minimal context with mocks to allow ProcessorTemplateHandler.setContext(...) to run.
        context = Mockito.mock(ITemplateContext.class, Mockito.RETURNS_DEEP_STUBS);
        // Provide a non-null template mode
        Mockito.when(context.getTemplateMode()).thenReturn(org.thymeleaf.templatemode.TemplateMode.HTML);

        // Mock configuration and attributes required by setContext
        IEngineConfiguration config = Mockito.mock(IEngineConfiguration.class, Mockito.RETURNS_DEEP_STUBS);
        Mockito.when(context.getConfiguration()).thenReturn(config);

        // Minimal non-null attribute/element definitions
        Mockito.when(config.getElementDefinitions()).thenReturn(Mockito.mock(org.thymeleaf.engine.ElementDefinitions.class, Mockito.RETURNS_DEEP_STUBS));
        Mockito.when(config.getAttributeDefinitions()).thenReturn(Mockito.mock(org.thymeleaf.engine.AttributeDefinitions.class, Mockito.RETURNS_DEEP_STUBS));

        handler = new ProcessorTemplateHandler();
        // Create and set the next handler in the chain
        nextHandler = Mockito.mock(ITemplateHandler.class);
        handler.setNext(nextHandler);
        handler.setContext(context);
    }

    @Test
    public void test_handleOpenElement_withNoAssociatedProcessors_delegatesToNextWhenNoModelProcessingNeeded() throws Exception {
        // Arrange
        // Prepare a dummy IOpenElementTag that will be passed to handleOpenElement
        final IOpenElementTag ioOpenTag = Mockito.mock(IOpenElementTag.class);
        // empty attributes
        Mockito.when(ioOpenTag.getAllAttributes()).thenReturn(new IAttribute[0]);
        Mockito.when(ioOpenTag.getTemplateMode()).thenReturn(org.thymeleaf.templatemode.TemplateMode.HTML);
        Mockito.when(ioOpenTag.getElementCompleteName()).thenReturn("div");
        Mockito.when(ioOpenTag.isSynthetic()).thenReturn(false);
        Mockito.when(ioOpenTag.getTemplateName()).thenReturn("template");
        Mockito.when(ioOpenTag.getLine()).thenReturn(1);
        Mockito.when(ioOpenTag.getCol()).thenReturn(1);

        // Provide a mock ElementDefinition and ensure no processors
        final ElementDefinition dummyDef = Mockito.mock(ElementDefinition.class);
        Mockito.when(ioOpenTag.getElementDefinition()).thenReturn(dummyDef);
        // No explicit stubbing for hasAssociatedProcessors(); default boolean return is false

        // Act
        Method m = ProcessorTemplateHandler.class.getDeclaredMethod("handleOpenElement", IOpenElementTag.class);
        m.setAccessible(true);
        m.invoke(handler, ioOpenTag);

        // Assert
        // Verify that the next handler was invoked to handleOpenElement on the converted tag
        Mockito.verify(nextHandler).handleOpenElement(Mockito.any(OpenElementTag.class));
    }

    @Test
    public void test_handleOpenElement_throttleStopped_queuedWhenRequested() throws Exception {
        // This test ensures that when throttling is enabled and stopProcessing is true, the event is queued
        // instead of being processed immediately.

        // Setup a flow controller that indicates processing should stop
        TemplateFlowController flowController = Mockito.mock(TemplateFlowController.class);
        // Attempt to set a public field stopProcessing to true via reflection (if present)
        try {
            Field f = TemplateFlowController.class.getField("stopProcessing");
            f.setBoolean(flowController, true);
        } catch (Exception e) {
            // If the field doesn't exist or is inaccessible, ignore; test should still compile/run
        }

        // Enable throttling on the handler (via setting the flow controller)
        handler.setFlowController(flowController);

        // Mock IOpenElementTag for the test
        final IOpenElementTag ioOpenTag = Mockito.mock(IOpenElementTag.class);
        Mockito.when(ioOpenTag.getAllAttributes()).thenReturn(new IAttribute[0]);
        Mockito.when(ioOpenTag.getTemplateMode()).thenReturn(org.thymeleaf.templatemode.TemplateMode.HTML);
        Mockito.when(ioOpenTag.getElementCompleteName()).thenReturn("span");
        Mockito.when(ioOpenTag.isSynthetic()).thenReturn(false);
        Mockito.when(ioOpenTag.getTemplateName()).thenReturn("template");
        Mockito.when(ioOpenTag.getLine()).thenReturn(1);
        Mockito.when(ioOpenTag.getCol()).thenReturn(1);

        final ElementDefinition dummyDef = Mockito.mock(ElementDefinition.class);
        Mockito.when(ioOpenTag.getElementDefinition()).thenReturn(dummyDef);

        Method m = ProcessorTemplateHandler.class.getDeclaredMethod("handleOpenElement", IOpenElementTag.class);
        m.setAccessible(true);
        m.invoke(handler, ioOpenTag);

        // We cannot observe private queue via public API here, but at least ensure no exception occurs
        assertNotNull(m);
    }
}

