class ProcessorTemplateHandlerHandleOpenElementTests {

    @Test
    void handleOpenElementAppliesAssociatedTagProcessorModification() {
        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(TemplateMode.HTML);
        resolver.setCacheable(false);

        final TemplateEngine templateEngine = new TemplateEngine();
        templateEngine.setTemplateResolver(resolver);
        templateEngine.addDialect(new AbstractProcessorDialect("test", "t", 1000) {
            @Override
            public Set<IProcessor> getProcessors(final String dialectPrefix) {
                return Collections.singleton(new AbstractElementTagProcessor(
                        TemplateMode.HTML, dialectPrefix, null, false, "replace", true, 1000) {
                    @Override
                    protected void doProcess(
                            final ITemplateContext context,
                            final IProcessableElementTag tag,
                            final IElementTagStructureHandler structureHandler) {
                        structureHandler.setBody("processed", false);
                    }
                });
            }
        });

        final String result = templateEngine.process(
                "<section t:replace=\"true\">original</section>",
                new Context());

        assertEquals("<section t:replace=\"true\">processed</section>", result);
    }
}

