package org.thymeleaf.standard.expression;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class LiteralSubstitutionUtilPerformLiteralSubstitutionTests {

    @Test
    void whenInputIsNull_returnsNull() {
        // null input should yield null per specification
        String result = LiteralSubstitutionUtil.performLiteralSubstitution(null);
        assertNull(result, "Expected null when input is null");
    }

    @Test
    void whenNoSubstitutionsPresent_returnsOriginalReference() {
        // If there are no substitutions, the original string should be returned unchanged
        final String input = "Just a plain string with no substitutions.";
        final String result = LiteralSubstitutionUtil.performLiteralSubstitution(input);
        assertSame(input, result, "Expected the original string instance to be returned when no substitutions are present");
    }

    @Test
    void transformsLiteralSubstitutionBetweenVariables() {
        // A substitution like |${onevar} ${twovar}| should be transformed to a Java-like concatenation
        // according to the specification: ${onevar} + ' ' + ${twovar}
        final String input = "|${onevar} ${twovar}|";
        final String expected = "${onevar} + ' ' + ${twovar}";
        final String result = LiteralSubstitutionUtil.performLiteralSubstitution(input);
        assertEquals(expected, result, "Literal substitution between two variable expressions should be transformed into a concatenation expression");
    }

    @Test
    void preservesEmptyLiteralSubstitution() {
        // An empty literal substitution || should be preserved (i.e., not mangled)
        final String input = "||";
        final String result = LiteralSubstitutionUtil.performLiteralSubstitution(input);
        // When empty, the implementation appends the two delimiters back, effectively keeping them as-is
        assertEquals("||", result, "Empty literal substitution should be preserved as two delimiters");
    }
}

package org.thymeleaf.standard.expression;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

import org.junit.jupiter.api.Test;

class LiteralSubstitutionUtilPerformLiteralSubstitutionTests {

    @Test
    void convertsAdjacentLiteralSubstitutionsIntoAValidConcatenation() {
        final String input = "|${first}||${second}|";

        final String result = LiteralSubstitutionUtil.performLiteralSubstitution(input);

        assertEquals("${first}${second}", result);
    }

    @Test
    void substitutesLiteralTextAroundAnExpression() {
        final String input = "|Hello ${name}!|";

        final String result = LiteralSubstitutionUtil.performLiteralSubstitution(input);

        assertEquals("'Hello ' + ${name} + '!'", result);
    }

    @Test
    void returnsNullForNullInput() {
        assertNull(LiteralSubstitutionUtil.performLiteralSubstitution(null));
    }

    @Test
    void leavesInputWithoutSubstitutionUnchanged() {
        final String input = "plain text";

        assertEquals(input, LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }
}

