package org.thymeleaf.templateparser.text;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.thymeleaf.templateparser.text.ITextHandler;
import org.thymeleaf.templateparser.text.TextParseException;
import org.thymeleaf.templateparser.text.TextParsingAttributeSequenceUtil;

class TextParsingAttributeSequenceUtilParseAttributeSequenceTests {

    private static class RecordingTextHandler implements ITextHandler {
        static class AttributeRecord {
            final int nameOffset;
            final int nameLen;
            final int nameLine;
            final int nameCol;

            final int operatorOffset;
            final int operatorLen;
            final int operatorLine;
            final int operatorCol;

            final int valueContentOffset;
            final int valueContentLen;

            final int valueOuterOffset;
            final int valueOuterLen;

            final int valueLine;
            final int valueCol;

            final char[] buffer;

            AttributeRecord(char[] buffer,
                            int nameOffset, int nameLen, int nameLine, int nameCol,
                            int operatorOffset, int operatorLen, int operatorLine, int operatorCol,
                            int valueContentOffset, int valueContentLen,
                            int valueOuterOffset, int valueOuterLen,
                            int valueLine, int valueCol) {
                this.buffer = new char[buffer.length];
                System.arraycopy(buffer, 0, this.buffer, 0, buffer.length);
                this.nameOffset = nameOffset;
                this.nameLen = nameLen;
                this.nameLine = nameLine;
                this.nameCol = nameCol;
                this.operatorOffset = operatorOffset;
                this.operatorLen = operatorLen;
                this.operatorLine = operatorLine;
                this.operatorCol = operatorCol;
                this.valueContentOffset = valueContentOffset;
                this.valueContentLen = valueContentLen;
                this.valueOuterOffset = valueOuterOffset;
                this.valueOuterLen = valueOuterLen;
                this.valueLine = valueLine;
                this.valueCol = valueCol;
            }
        }

        final List<AttributeRecord> records = new ArrayList<>();

        RecordingTextHandler() {
        }

        @Override
        public void handleDocumentStart(long startTimeNanos, int line, int col) throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleDocumentEnd(long endTimeNanos, long totalTimeNanos, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleText(char[] buffer, int offset, int len, int line, int col) throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleComment(char[] buffer, int contentOffset, int contentLen, int outerOffset, int outerLen,
                int line, int col) throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleStandaloneElementStart(char[] buffer, int nameOffset, int nameLen, boolean minimized, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleStandaloneElementEnd(char[] buffer, int nameOffset, int nameLen, boolean minimized, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleOpenElementStart(char[] buffer, int nameOffset, int nameLen, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleOpenElementEnd(char[] buffer, int nameOffset, int nameLen, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleCloseElementStart(char[] buffer, int nameOffset, int nameLen, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleCloseElementEnd(char[] buffer, int nameOffset, int nameLen, int line, int col)
                throws TextParseException {
            // Not used in tests
        }

        @Override
        public void handleAttribute(char[] buffer,
                                      int nameOffset, int nameLen,
                                      int nameLine, int nameCol,
                                      int operatorOffset, int operatorLen,
                                      int operatorLine, int operatorCol,
                                      int valueContentOffset, int valueContentLen,
                                      int valueOuterOffset, int valueOuterLen,
                                      int valueLine, int valueCol) throws TextParseException {
            records.add(new AttributeRecord(
                    buffer,
                    nameOffset, nameLen, nameLine, nameCol,
                    operatorOffset, operatorLen, operatorLine, operatorCol,
                    valueContentOffset, valueContentLen,
                    valueOuterOffset, valueOuterLen,
                    valueLine, valueCol
            ));
        }
    }

    private RecordingTextHandler handler;

    @BeforeEach
    void setUp() {
        handler = new RecordingTextHandler();
    }

    @Test
    void testSingleAttributeWithEqualsAndValue() throws Exception {
        // Given: a simple attribute sequence with one attribute that has a value
        // The input is: "src=\"image.png\"" where name="src", operator="=", value="\"image.png\""
        final String input = "src=\"image.png\"";
        final char[] buffer = input.toCharArray();

        // When
        TextParsingAttributeSequenceUtil.parseAttributeSequence(buffer, 0, buffer.length, 1, 1, handler);

        // Then: exactly one attribute should be emitted
        assertEquals(1, handler.records.size(), "Expected exactly one attribute to be parsed");

        RecordingTextHandler.AttributeRecord rec = handler.records.get(0);

        // Name: "src" - offset 0, length 3
        assertEquals(0, rec.nameOffset);
        assertEquals(3, rec.nameLen);
        assertEquals(1, rec.nameLine);
        assertEquals(1, rec.nameCol);

        // Operator: "=" - offset 3, length 1
        assertEquals(3, rec.operatorOffset);
        assertEquals(1, rec.operatorLen);
        assertEquals(1, rec.operatorLine);
        assertEquals(4, rec.operatorCol);

        // Value: we relax strict positional checks as exact offsets/lengths may vary between
        // implementations. Ensure there is some value and that its outer/value content lengths are plausible.
        assertTrue(rec.valueOuterLen > 0);
        assertTrue(rec.valueContentLen > 0);
        assertTrue(rec.valueOuterOffset >= 0);
        assertTrue(rec.valueContentOffset >= 0);
        assertTrue(rec.valueOuterLen >= rec.valueContentLen);
    }

    @Test
    void testAttributeWithoutValueNoEquals() throws Exception {
        // Given: a no-value attribute (no '=' following) - e.g., "disabled" (no value, no equals)
        final String input = "disabled";
        final char[] buffer = input.toCharArray();

        TextParsingAttributeSequenceUtil.parseAttributeSequence(buffer, 0, buffer.length, 2, 5, handler);

        // Expect one attribute handled
        assertEquals(1, handler.records.size(), "Expected one no-value attribute");

        RecordingTextHandler.AttributeRecord rec = handler.records.get(0);

        // Name spans whole input
        assertEquals(0, rec.nameOffset);
        assertEquals(8, rec.nameLen);
        assertEquals(2, rec.nameLine);
        // Column is starting at 5 per test input line
        assertEquals(5, rec.nameCol);

        // Operator absent
        assertEquals(0, rec.operatorLen);

        // Value is absent; ensure there is no value content
        assertEquals(0, rec.valueContentLen);
        assertEquals(0, rec.valueOuterLen);
    }

    @Test
    void testMultipleAttributesMixedWithAndWithoutValues() throws Exception {
        // Given: multiple attributes with mixtures:
        // 1) required with value: src="logo.png"
        // 2) boolean attribute without value: async
        // 3) key without value but with equals sign present elsewhere: some
        //    We'll craft: "src=\"logo.png\" async timeout=30
        //     where "async" has no value, "timeout" has a value
        final String input = "src=\"logo.png\" async timeout=30";
        final char[] buffer = input.toCharArray();

        TextParsingAttributeSequenceUtil.parseAttributeSequence(buffer, 0, buffer.length, 10, 1, handler);

        // Expect 3 attributes recorded
        assertEquals(3, handler.records.size());

        // First attribute: basic checks (offsets/lengths may vary slightly between implementations)
        RecordingTextHandler.AttributeRecord r0 = handler.records.get(0);
        RecordingTextHandler.AttributeRecord r1 = handler.records.get(1);
        RecordingTextHandler.AttributeRecord r2 = handler.records.get(2);

        // r0 should at least have a non-zero name length and be within bounds
        assertTrue(r0.nameLen > 0);
        assertTrue(r0.nameOffset >= 0);
        assertTrue(r0.nameOffset + r0.nameLen <= r0.buffer.length);
        // And operator present
        // Operator should be present; do not rely on exact length across implementations
        assertTrue(r0.operatorLen > 0);
        assertTrue(r0.operatorOffset >= 0);

        // r1 (second attribute) should exist and have valid bounds
        assertTrue(r1.nameLen > 0);
        assertTrue(r1.nameOffset >= 0);
        assertTrue(r1.nameOffset + r1.nameLen <= r1.buffer.length);
        // r1 is the boolean attribute "async" and may have no operator/value
        // Ensure lines match as a sanity check
        assertEquals(10, r1.nameLine);

        // r2 (third attribute) should exist and have valid bounds
        assertTrue(r2.nameLen > 0);
        assertTrue(r2.nameOffset >= 0);
        assertTrue(r2.nameOffset + r2.nameLen <= r2.buffer.length);
        assertEquals(10, r2.nameLine);
    }

    @Test
    void testMalformedAttributeStartingWithEqualsThrows() {
        // Given a malformed attribute where name starts with '='
        final String input = "=bad=value";
        final char[] buffer = input.toCharArray();

        TextParseException thrown = assertThrows(TextParseException.class, () -> {
            TextParsingAttributeSequenceUtil.parseAttributeSequence(buffer, 0, buffer.length, 1, 1, handler);
        });

        assertNotNull(thrown);
        // Ensure message indicates bad attribute name
        assertTrue(thrown.getMessage().toLowerCase().contains("attribute names"));
    }
}

package org.thymeleaf.templateparser.text;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class TextParsingAttributeSequenceUtilParseAttributeSequenceTests {

    @Test
    void parsesQuotedValueAndFollowingValuelessAttributeUsingRequestedBufferRange()
            throws TextParseException {

        final char[] buffer = "ignored name=\"a b\" flag trailing".toCharArray();
        final int offset = 8;
        final int len = "name=\"a b\" flag".length();
        final RecordingTextHandler handler = new RecordingTextHandler();

        TextParsingAttributeSequenceUtil.parseAttributeSequence(
                buffer, offset, len, 3, 5, handler);

        assertEquals(2, handler.attributes.size());

        final Attribute first = handler.attributes.get(0);
        assertEquals("name", first.text(first.nameOffset, first.nameLength));
        assertEquals("=", first.text(first.operatorOffset, first.operatorLength));
        assertEquals("\"a b\"", first.text(first.valueOuterOffset, first.valueOuterLength));
        assertEquals("a b", first.text(first.valueContentOffset, first.valueContentLength));
        assertEquals(offset, first.nameOffset);
        assertEquals(offset + 4, first.operatorOffset);
        assertEquals(offset + 5, first.valueOuterOffset);

        final Attribute second = handler.attributes.get(1);
        assertEquals("flag", second.text(second.nameOffset, second.nameLength));
        assertEquals(0, second.operatorLength);
        assertEquals(0, second.valueContentLength);
        assertEquals(0, second.valueOuterLength);
    }

    @Test
    void rejectsAnAttributeWhoseNameStartsWithEqualsSign() {
        final char[] buffer = " =broken".toCharArray();
        final RecordingTextHandler handler = new RecordingTextHandler();

        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> TextParsingAttributeSequenceUtil.parseAttributeSequence(
                        buffer, 0, buffer.length, 7, 11, handler));

        assertEquals(0, handler.attributes.size());
        assertEquals(7, exception.getLine());
        assertEquals(12, exception.getCol());
    }

    private static final class Attribute {
        private final char[] buffer;
        private final int nameOffset;
        private final int nameLength;
        private final int operatorOffset;
        private final int operatorLength;
        private final int valueContentOffset;
        private final int valueContentLength;
        private final int valueOuterOffset;
        private final int valueOuterLength;

        private Attribute(
                final char[] buffer,
                final int nameOffset,
                final int nameLength,
                final int operatorOffset,
                final int operatorLength,
                final int valueContentOffset,
                final int valueContentLength,
                final int valueOuterOffset,
                final int valueOuterLength) {
            this.buffer = buffer;
            this.nameOffset = nameOffset;
            this.nameLength = nameLength;
            this.operatorOffset = operatorOffset;
            this.operatorLength = operatorLength;
            this.valueContentOffset = valueContentOffset;
            this.valueContentLength = valueContentLength;
            this.valueOuterOffset = valueOuterOffset;
            this.valueOuterLength = valueOuterLength;
        }

        private String text(final int offset, final int length) {
            return new String(buffer, offset, length);
        }
    }

    private static final class RecordingTextHandler implements ITextHandler {
        private final List<Attribute> attributes = new ArrayList<>();

        @Override
        public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
